package io.yak.ops.common.bean.dto.modeling.metric;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.util.List;
import lombok.Getter;
import lombok.Setter;

/**
 * Submitted parts of one derived metric.
 *
 * <p>The composed code and name are generated by the server; only the parts are editable input.
 * Modifiers carry a submitted order that the composition preserves.
 */
@Getter
@Setter
public class MetricDerivedInputDTO {
    /** Atomic metric of the same Workspace that carries the caliber. */
    @NotBlank(message = "必填参数不能为空")
    @Size(max = 64, message = "参数长度超过限制")
    private String atomicMetricId;

    /** Time period of the same Workspace that fixes the window. */
    @NotBlank(message = "必填参数不能为空")
    @Size(max = 64, message = "参数长度超过限制")
    private String periodId;

    /** Modifiers of the same Workspace in submitted order; the same modifier may not repeat. */
    private List<@Size(max = 64, message = "参数长度超过限制") String> modifierIds;

    /** Accountable owner; defaults to the caller when omitted. */
    @Size(max = 64, message = "负责人标识过长")
    private String ownerId;

    @Size(max = 500, message = "文本长度超过限制")
    private String description;
}
